import ast
from pathlib import Path
for p in Path('backend/app').rglob('*.py'):
    if '/tests/' in str(p): continue
    try: src=p.read_text(encoding='utf-8'); tree=ast.parse(src)
    except Exception: continue
    findings=[]
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and getattr(node,'end_lineno',None):
            size=node.end_lineno-node.lineno+1
            limit=90 if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) else 300
            if size>=limit: findings.append((size,type(node).__name__,node.name,node.lineno))
    if findings:
        print(p)
        for item in sorted(findings,reverse=True): print(' ',item)
